#!/bin/sh
# The committed generated files must be what run.py produces from the committed sources.
# Generation is deterministic; a mismatch means a hand edit or a forgotten regeneration.
set -e
cd "$(dirname "$0")/.."
GEN="gas/Shell_version.gs gas/Archetype_ch10_cc.gs gas/Archetype_ch10_cc_test.gs output/ch10_cc.bundle.json gas/Units.gs gas/Tone.gs gas/Archetype_ch13_eq_test.gs gas/Archetype_ch14_ph_test.gs gas/Archetype_ch14_ph.gs output/ch14_ph.bundle.json gas/Archetype_ch14_acidbase_test.gs gas/Archetype_ch14_acidbase.gs output/ch14_acidbase.bundle.json gas/Archetype_ch14_buffer_test.gs gas/Archetype_ch14_buffer.gs output/ch14_buffer.bundle.json gas/Archetype_ch14_titration_test.gs gas/Archetype_ch14_titration.gs output/ch14_titration.bundle.json gas/Archetype_ch15_ksp_test.gs gas/Archetype_ch15_ksp.gs output/ch15_ksp.bundle.json gas/Archetype_ch15_common_ion_test.gs gas/Archetype_ch15_common_ion.gs output/ch15_common_ion.bundle.json gas/Archetype_ch15_qsp_test.gs gas/Archetype_ch15_qsp.gs output/ch15_qsp.bundle.json gas/Archetype_ch15_complex_test.gs gas/Archetype_ch15_complex.gs output/ch15_complex.bundle.json gas/Archetype_ch16_entropy_test.gs gas/Archetype_ch16_entropy.gs output/ch16_entropy.bundle.json gas/Archetype_ch16_free_energy_test.gs gas/Archetype_ch16_free_energy.gs output/ch16_free_energy.bundle.json gas/Archetype_ch16_spontaneity_test.gs gas/Archetype_ch16_spontaneity.gs output/ch16_spontaneity.bundle.json gas/Archetype_ch16_equilibrium_G_test.gs gas/Archetype_ch16_equilibrium_G.gs output/ch16_equilibrium_G.bundle.json gas/Archetype_ch16_G_and_K_test.gs gas/Archetype_ch16_G_and_K.gs output/ch16_G_and_K.bundle.json gas/Archetype_ch17_balancing_test.gs gas/Archetype_ch17_balancing.gs output/ch17_balancing.bundle.json gas/Archetype_ch17_cell_test.gs gas/Archetype_ch17_cell.gs output/ch17_cell.bundle.json gas/Archetype_ch17_E_G_K_test.gs gas/Archetype_ch17_E_G_K.gs output/ch17_E_G_K.bundle.json gas/Archetype_ch17_nernst_test.gs gas/Archetype_ch17_nernst.gs output/ch17_nernst.bundle.json gas/Archetype_ch17_electrolysis_test.gs gas/Archetype_ch17_electrolysis.gs output/ch17_electrolysis.bundle.json gas/Archetype_ch19_cft_test.gs gas/Archetype_ch19_cft.gs output/ch19_cft.bundle.json gas/Archetype_ch21_decay_test.gs gas/Archetype_ch21_decay.gs output/ch21_decay.bundle.json gas/Archetype_ch21_binding_test.gs gas/Archetype_ch21_binding.gs output/ch21_binding.bundle.json gas/Archetype_ch13_eq.gs output/ch13_eq.bundle.json gas/Archetype_ch11_colligative.gs output/ch11_colligative.bundle.json output/ch11_colligative.samples.json"
mkdir -p /tmp/_gen_before
for f in $GEN; do cp "$f" /tmp/_gen_before/$(basename "$f"); done
python3 run.py all --per-kind 3 --seed 1 > /tmp/_gen_log.txt
cat /tmp/_gen_log.txt
bad=0
for f in $GEN; do cmp -s "$f" /tmp/_gen_before/$(basename "$f") || { echo "generated-check: $f differs"; bad=1; }; cp /tmp/_gen_before/$(basename "$f") "$f"; done
if [ "$bad" -eq 0 ]; then echo "generated-check: committed generated files match run.py output."
else echo "generated-check: FAILED. Run 'make generate' and commit."; exit 1; fi
